#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto doOp = [&](int x, int y){
        ops.push_back({x,y});
        vector<int> np(n);
        for(int i=0;i<y;i++) np[i]=p[n-y+i];
        for(int i=0;i<n-x-y;i++) np[y+i]=p[x+i];
        for(int i=0;i<x;i++) np[n-x+i]=p[i];
        p=np;
    };

    for(int placed=0;placed<n;placed++){
        int pos=-1;
        for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        if(pos==placed) continue;
        // Move element from pos to placed
        // Step 1: rotate so element goes to position 0
        if(pos>0 && pos<n){
            doOp(pos, n-pos);
            pos=0;
        }
        // Now element is at position 0, move to 'placed'
        if(placed>0 && placed<n){
            doOp(n-placed, placed);
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
